CREATE TABLE event_feedback (id BIGSERIAL PRIMARY KEY,event_id BIGINT NOT NULL REFERENCES events(id) ON DELETE CASCADE,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,rating SMALLINT NOT NULL CHECK(rating BETWEEN 1 AND 5),comments VARCHAR(2000),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT uk_event_feedback_event_user UNIQUE(event_id,user_id));
CREATE INDEX idx_event_feedback_event ON event_feedback(event_id,created_at DESC);
CREATE TABLE event_certificates (id BIGSERIAL PRIMARY KEY,registration_id BIGINT NOT NULL UNIQUE REFERENCES event_registrations(id) ON DELETE CASCADE,certificate_number VARCHAR(48) NOT NULL UNIQUE,issued_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
